#include <stddef.h>
typedef struct {
    int direction;
    int periph_inc;
    int mem_inc;
    int count;
    int buf_a_size;
    int buf_b_size;
} DmaConfig;

int dma_check_config(const DmaConfig *cfg)
{
    if (cfg == NULL) {
        return -1;
    }
    if (cfg->count <= 0) {
        return -1;
    }
    if (cfg->direction != 0 && cfg->direction != 1) {
        return -1;
    }
    if (cfg->buf_a_size < 0 || cfg->buf_b_size < 0) {
        return -1;
    }

    int flags = 0;

    if (cfg->periph_inc != 0) {
        flags |= 1;  /* 外设数据寄存器地址应固定 */
    }
    if (cfg->mem_inc == 0) {
        flags |= 2;  /* 内存缓冲区地址需要逐项递增 */
    }

    if (cfg->buf_b_size > 0) {
        if (cfg->buf_a_size < cfg->count || cfg->buf_b_size < cfg->count) {
            flags |= 4;
        }
    } else {
        if (cfg->buf_a_size < cfg->count) {
            flags |= 4;
        }
    }

    return flags;
}
